SELECT u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.pwd_update_date, u.create_by, u.create_time, u.update_by, u.update_time, u.remark, u.user_category, u.identity_id, u.account_status, u.enrollment_date, u.graduation_date, u.teacher_code, u.title, u.education, d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader, d.status as dept_status, r.role_id, r.role_name, r.role_key, r.role_sort, r.data_scope, r.status as role_status FROM `yu-CjluJwc`.sys_user u LEFT JOIN `yu-CjluJwc`.sys_dept d ON u.dept_id = d.dept_id LEFT JOIN `yu-CjluJwc`.brm_teacher bt ON u.user_id = bt.user_id LEFT JOIN `yu-CjluJwc`.sys_user_role ur ON u.user_id = ur.user_id LEFT JOIN `yu-CjluJwc`.sys_role r ON r.role_id = ur.role_id WHERE u.user_name = 'admin' AND u.del_flag = '0';
